import { createHash } from "node:crypto";

export const SESSION_TOKEN_HASH_PREFIX = "sha256:";
const SESSION_TOKEN_HASH_RE = /^sha256:[0-9a-f]{64}$/;

// Session tokens are 256-bit random values generated by `randomToken()`. A
// single SHA-256 digest is sufficient for a high-entropy credential: there is
// no dictionary to attack, so a slow password hash or a per-row salt would add
// cost without adding meaningful protection.
export function hashSessionToken(rawToken) {
  if (typeof rawToken !== "string" || rawToken.length === 0) return "";
  return `${SESSION_TOKEN_HASH_PREFIX}${createHash("sha256").update(rawToken, "utf8").digest("hex")}`;
}

export function isSessionTokenHash(value) {
  return typeof value === "string" && SESSION_TOKEN_HASH_RE.test(value);
}

function columns(db, table) {
  return new Set(
    db
      .prepare(
        "SELECT column_name FROM information_schema.columns WHERE table_schema = current_schema() AND table_name = ?"
      )
      .all(table)
      .map((row) => row.column_name)
  );
}

function primaryKey(db, table) {
  const rows = db
    .prepare(
      `SELECT tc.constraint_name AS name, kcu.column_name AS column
       FROM information_schema.table_constraints tc
       JOIN information_schema.key_column_usage kcu
         ON kcu.constraint_name = tc.constraint_name
        AND kcu.constraint_schema = tc.constraint_schema
       WHERE tc.table_schema = current_schema()
         AND tc.table_name = ?
         AND tc.constraint_type = 'PRIMARY KEY'
       ORDER BY kcu.ordinal_position`
    )
    .all(table);
  return { name: rows[0]?.name || null, columns: rows.map((row) => row.column) };
}

// One-way migration from plaintext `token` to `token_hash`. It is safe to run
// repeatedly: only rows with a NULL hash are derived from the legacy column,
// and once the column is gone there is nothing left to hash.
export function migrateLegacySessionTable(db, table = "sessions") {
  if (!/^[a-z_][a-z0-9_]*$/.test(table)) {
    throw new Error(`Invalid session table name: ${table}`);
  }
  const quoted = `"${table}"`;
  let existing = columns(db, table);
  if (existing.size === 0) return { migrated: 0, hadLegacyToken: false };

  if (!existing.has("token_hash")) {
    db.exec(`ALTER TABLE ${quoted} ADD COLUMN IF NOT EXISTS token_hash TEXT`);
    existing = columns(db, table);
  }

  let migrated = 0;
  const hadLegacyToken = existing.has("token");
  if (hadLegacyToken) {
    // Empty tokens can never authenticate (lookups reject falsy input), so
    // they carry no value worth migrating.
    db.exec(`DELETE FROM ${quoted} WHERE token IS NULL OR token = ''`);
    const rows = db.prepare(`SELECT token FROM ${quoted} WHERE token_hash IS NULL`).all();
    for (const row of rows) {
      db.prepare(`UPDATE ${quoted} SET token_hash = ? WHERE token = ?`).run(
        hashSessionToken(row.token),
        row.token
      );
      migrated += 1;
    }
    const unresolved = db
      .prepare(`SELECT COUNT(*) AS c FROM ${quoted} WHERE token_hash IS NULL`)
      .get().c;
    if (Number(unresolved) !== 0) {
      throw new Error(
        `Session token migration left ${unresolved} row(s) without a hash in ${table}; refusing to drop plaintext tokens`
      );
    }
    // Dropping `token` also drops a primary key defined on it.
    db.exec(`ALTER TABLE ${quoted} DROP COLUMN token`);
  }

  const invalid = db
    .prepare(
      `SELECT COUNT(*) AS c FROM ${quoted}
       WHERE token_hash IS NOT NULL AND token_hash !~ '^sha256:[0-9a-f]{64}$'`
    )
    .get().c;
  if (Number(invalid) !== 0) {
    throw new Error(
      `Session token migration found ${invalid} non-canonical hash(es) in ${table}; refusing to continue`
    );
  }

  db.exec(`ALTER TABLE ${quoted} ALTER COLUMN token_hash SET NOT NULL`);
  const key = primaryKey(db, table);
  if (!(key.columns.length === 1 && key.columns[0] === "token_hash")) {
    if (key.name) {
      db.exec(`ALTER TABLE ${quoted} DROP CONSTRAINT "${key.name.replace(/"/g, '""')}"`);
    }
    db.exec(`ALTER TABLE ${quoted} ADD CONSTRAINT "${table}_pkey" PRIMARY KEY (token_hash)`);
  }
  return { migrated, hadLegacyToken };
}

export function migrateLegacySessionTokens(db) {
  return migrateLegacySessionTable(db, "sessions");
}
